// Validate request and normalize fields.
// Webhook auth (X-Mailhub-Secret) ist bereits durch Webhook-Node geprueft.

const input = $input.first().json;
const body = input.body || input;

const ALLOWED_FROM = [
  'ceo@whitestag.ai',
  'cmo@whitestag.ai',
  'cto@whitestag.ai',
  'cpo@whitestag.ai',
  'cro@whitestag.ai',
  'creative@whitestag.ai',
  'dpo@whitestag.ai',
  'webdesign@whitestag.ai',
  'health@whitestag.ai',
  'office@whitestag.ai',
  'paperclip@clara-werden.de',
];

function reject(message) {
  return [{ json: { __invalid: true, errorMessage: message } }];
}

const from = String(body.from || '').trim().toLowerCase();
const to = String(body.to || '').trim();
const subject = String(body.subject || '').trim();
const text = body.text != null ? String(body.text) : '';
let html = body.html != null ? String(body.html) : '';
const cc = body.cc != null ? String(body.cc) : '';
const inReplyTo = body.inReplyTo != null ? String(body.inReplyTo) : '';
const replyTo = body.replyTo != null ? String(body.replyTo) : '';
const signatur = body.signatur != null ? String(body.signatur).trim() : '';

if (!ALLOWED_FROM.includes(from)) {
  return reject('Unauthorized from-address: ' + (from || '(empty)'));
}
if (!to) return reject('Missing required field: to');
if (!subject) return reject('Missing required field: subject');
if (!text && !html) return reject('Missing required field: text (or html)');

// --- Aussen-Sperre (Agenten-Guard) ---------------------------------------
// Kein Paperclip-Agent sendet ohne Freigabe an einen echten externen Empfaenger.
// office@ (Luna, Phase 2) am strengsten: NUR ws@whitestag.ai.
// Alle anderen Agenten: nur interne Ziele (whitestag.*, sorbART, Clara) + Walter.
const INTERNAL_DOMAINS = ['whitestag.ai','whitestag.de','whitestag.film','sorbart.de','sorbart.shop','clara-werden.de','clara-sound.de'];
// Walter wird ausschliesslich ueber ws@whitestag.ai erreicht (gmail + schoenenbroecher.de gestrichen 2026-07-22).
function _isInternalTarget(addr) {
  const dom = (String(addr).toLowerCase().split('@')[1] || '');
  return INTERNAL_DOMAINS.includes(dom);
}
{
  const combined = [to, cc].filter(Boolean).join(',');
  const addrs = (combined.match(/[\w.+-]+@[\w.-]+\.\w+/g) || []).map(a => a.toLowerCase());
  if (from === 'office@whitestag.ai') {
    const APPROVAL_SECRET = 'luna-approval-b482e1347a3aa8e0ef8aa5765d8b13bd';
    const approval = String(body.approval || '').trim();
    const onlyWalter = addrs.length > 0 && addrs.every(a => a === 'ws@whitestag.ai');
    const approved = approval.length > 0 && approval === APPROVAL_SECRET;
    if (!onlyWalter && !approved) return reject('Phase-3-Gate: office@ (Luna) an Externe nur mit gueltiger Freigabe. Blockiert: to=' + to + (cc ? ' cc=' + cc : ''));
  } else {
    const ext = addrs.filter(a => !_isInternalTarget(a));
    if (ext.length) return reject('Aussen-Sperre: Agenten duerfen ohne Freigabe nicht an externe Empfaenger senden. Blockiert: ' + ext.join(', '));
  }
}


// Optional attachments: Array von { filename, content (base64), mimeType? }
const rawAttachments = Array.isArray(body.attachments) ? body.attachments : [];
const attachments = [];
for (const [i, a] of rawAttachments.entries()) {
  if (!a || typeof a !== 'object') return reject(`Attachment #${i}: not an object`);
  const filename = String(a.filename || '').trim();
  const content = String(a.content || '').trim();
  if (!filename) return reject(`Attachment #${i}: missing filename`);
  if (!content) return reject(`Attachment #${i}: missing content (base64)`);
  const mimeType = String(a.mimeType || 'application/octet-stream');
  const cid = a.cid ? String(a.cid).trim() : '';
  attachments.push({ filename, content, mimeType, ...(cid ? {cid} : {}) });
}

// --- Auto-HTML: wenn kein html geliefert wurde, aus markdown text aufbauen ----
// Konsistent zum lib/build_walter_mail_html.py Layout (eine "Bericht"-Sektion).
function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function stripFrontmatter(md) {
  return md.replace(/^---\n[\s\S]*?\n---\n+/, '');
}

function mdToHtml(md) {
  if (!md) return '';
  md = stripFrontmatter(md);

  // Fenced code blocks first (extract & placeholder)
  const codeBlocks = [];
  md = md.replace(/```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g, (m, lang, code) => {
    const i = codeBlocks.length;
    codeBlocks.push(`<pre style="background:#f6f8fa;padding:12px;border-radius:4px;overflow:auto;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px;"><code>${escapeHtml(code)}</code></pre>`);
    return `@@CODEBLOCK${i}@@`;
  });

  const lines = md.split('\n');
  const out = [];
  let inList = null; // 'ul' | 'ol' | null
  let para = [];

  function flushPara() {
    if (para.length) {
      out.push(`<p style="margin:8px 0;">${inlineMd(para.join(' '))}</p>`);
      para = [];
    }
  }
  function closeList() {
    if (inList) { out.push(`</${inList}>`); inList = null; }
  }

  function inlineMd(s) {
    s = escapeHtml(s);
    // links [text](url)
    s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color:#0066cc;text-decoration:none;">$1</a>');
    // bold **x** / __x__
    s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    s = s.replace(/__([^_]+)__/g, '<strong>$1</strong>');
    // italic *x* / _x_
    s = s.replace(/(^|[\s(])\*([^*\n]+)\*/g, '$1<em>$2</em>');
    s = s.replace(/(^|[\s(])_([^_\n]+)_/g, '$1<em>$2</em>');
    // inline code `x`
    s = s.replace(/`([^`]+)`/g, '<code style="background:#f6f8fa;padding:1px 4px;border-radius:3px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px;">$1</code>');
    // restore code-block placeholders
    s = s.replace(/@@CODEBLOCK(\d+)@@/g, (_, i) => codeBlocks[Number(i)]);
    return s;
  }

  for (const raw of lines) {
    const line = raw.replace(/\s+$/, '');

    if (!line.trim()) { flushPara(); continue; } // blank lines inside a list don't close it (loose-list handling)

    // headings
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    if (h) {
      flushPara(); closeList();
      const lvl = h[1].length;
      const size = [22, 18, 16, 15, 14, 14][lvl - 1];
      const margin = lvl <= 2 ? '24px 0 8px 0' : '16px 0 6px 0';
      const border = lvl === 2 ? 'border-bottom:1px solid #eee;padding-bottom:4px;' : '';
      out.push(`<h${lvl} style="font-size:${size}px;margin:${margin};color:#${lvl<=2?'333':'555'};${border}">${inlineMd(h[2])}</h${lvl}>`);
      continue;
    }

    // unordered list
    const ul = line.match(/^[-*+]\s+(.*)$/);
    if (ul) {
      flushPara();
      if (inList !== 'ul') { closeList(); out.push('<ul style="margin:8px 0;padding-left:24px;">'); inList = 'ul'; }
      out.push(`<li style="margin:2px 0;">${inlineMd(ul[1])}</li>`);
      continue;
    }
    // ordered list
    const ol = line.match(/^\d+\.\s+(.*)$/);
    if (ol) {
      flushPara();
      if (inList !== 'ol') { closeList(); out.push('<ol style="margin:8px 0;padding-left:24px;">'); inList = 'ol'; }
      out.push(`<li style="margin:2px 0;">${inlineMd(ol[1])}</li>`);
      continue;
    }

    // code-block placeholder on its own line
    if (/^@@CODEBLOCK\d+@@$/.test(line)) {
      flushPara(); closeList();
      out.push(inlineMd(line));
      continue;
    }

    // paragraph accumulator
    closeList();
    para.push(line);
  }
  flushPara(); closeList();

  return out.join('\n');
}

if (!html && text) {
  const agentLabel = from.split('@')[0].toUpperCase();
  const bodyHtml = mdToHtml(text);
  html = [
    '<!DOCTYPE html>',
    '<html><head><meta charset="utf-8"></head>',
    '<body style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.5;color:#222;max-width:780px;margin:0 auto;padding:20px;">',
    `<h1 style="font-size:22px;margin:0 0 4px 0;color:#111;">\u{1F4EC} ${escapeHtml(subject)}</h1>`,
    `<div style="color:#888;font-size:13px;margin-bottom:24px;">${escapeHtml(agentLabel)} · ${escapeHtml(from)}</div>`,
    '<h2 style="font-size:16px;margin:24px 0 8px 0;color:#444;border-bottom:1px solid #eee;padding-bottom:4px;">\u{1F4CB} Inhalt</h2>',
    `<div style="margin-bottom:8px;">${bodyHtml}</div>`,
    '</body></html>',
  ].join('\n');
}

// agentKey for Switch routing (lowercased local part)
const agentKey = from.split('@')[0];

return [{
  json: {
    __invalid: false,
    agentKey,
    from,
    to,
    subject,
    text,
    html,
    cc,
    inReplyTo,
    replyTo,
    attachments,
    signatur,
  }
}];

// Webhook-Felder aus Validate Request (vor SMTP Send, sonst überschrieben)
const req = $('Validate Request').first().json;
// SMTP-Response aus aktuellem Item
const smtp = $input.first().json;

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ts = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

const from = String(req.from || '?');
const to = String(req.to || '?');
const cc = String(req.cc || '').trim();
const subject = String(req.subject || '(ohne Betreff)').replace(/[\r\n]+/g, ' ').slice(0, 200);
const messageId = String(smtp.messageId || (smtp.envelope && smtp.envelope.messageId) || '');
const ccPart = cc ? ` (cc: \`${cc}\`)` : '';

const line = `- **${ts}** \`${from}\` → \`${to}\`${ccPart} · *${subject}* · msgId \`${messageId}\`\n`;

return [{
  json: { ...smtp, logLine: line },
  binary: {
    data: {
      data: Buffer.from(line, 'utf8').toString('base64'),
      mimeType: 'text/markdown; charset=utf-8',
      fileExtension: 'md',
      fileName: 'Mailhub-Outbound-Log.md',
    },
  },
}];

const items = $input.all();
return items.map(item => {
  const json = item.json;
  const list = Array.isArray(json.attachments) ? json.attachments : [];
  const binary = {};
  list.forEach((att, i) => {
    binary[`attachment_${i}`] = {
      data: att.content,
      mimeType: att.mimeType || 'application/octet-stream',
      fileName: att.filename,
      ...(att.cid ? { contentId: att.cid } : {}),
    };
  });
  json.__attachmentKeys = list.length > 0 ? list.map((_, i) => `attachment_${i}`).join(',') : '';
  return { json, binary };
});

// Signaturlogik des SMTP-Relays.
//
// Spiegelt signatur.py. Wird als Code-Node "Attach Signature" in den Relay
// eingesetzt (siehe patch_relay.py) und liegt hier als eigene Datei, damit
// sie testbar bleibt.
//
// GRUNDREGEL: Diese Funktion darf niemals werfen. Der Relay ist der einzige
// Mailweg; ueber ihn laufen auch die Waechter-Alarme. Im Fehlerfall geht die
// Mail ohne Signatur raus und __signaturFehler traegt den Grund.

const BAUSTEIN_VERZEICHNIS =
  '/Users/walterschoenenbroecher.de/.paperclip/scripts/signatur';

const BEREICHE = ['ai', 'film', 'tv', 'academy', 'app', 'de'];
const VORGABE_BEREICH = 'ai';

const ABSENDER = {
  'ceo@whitestag.ai':       { name: 'CEO', rolle: 'KI-Agent' },
  'cmo@whitestag.ai':       { name: 'CMO', rolle: 'KI-Agent' },
  'cto@whitestag.ai':       { name: 'CTO', rolle: 'KI-Agent' },
  'cpo@whitestag.ai':       { name: 'CPO', rolle: 'KI-Agent' },
  'cro@whitestag.ai':       { name: 'CRO', rolle: 'KI-Agent' },
  'creative@whitestag.ai':  { name: 'Creative Director', rolle: 'KI-Agent' },
  'dpo@whitestag.ai':       { name: 'DPO', rolle: 'KI-Agent' },
  'webdesign@whitestag.ai': { name: 'Web-Design Specialist', rolle: 'KI-Agent' },
  'health@whitestag.ai':    { name: 'CHO', rolle: 'KI-Agent' },
  // office@ ist Luna. Sie signiert selbst und sendet signatur:"none" — der
  // Eintrag ist das Sicherheitsnetz, falls ein Skript als office@ ohne
  // eigene Signatur sendet.
  'office@whitestag.ai':    { name: 'Luna', rolle: 'KI-Assistentin' },
};

// Spiegelt Pythons html.escape(s, quote=True) — inkl. Apostroph, damit
// beide Implementierungen bei jedem Namen/jeder Rolle byte-identisch
// bleiben, nicht nur fuer die heute hinterlegten ABSENDER-Werte.
function maskiere(s) {
  return String(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#x27;');
}

function hinweisFuer(eintrag) {
  if (eintrag.rolle === 'KI-Assistentin') {
    return 'Diese Nachricht wurde von Luna, unserer KI-Assistentin, vorbereitet.';
  }
  return `Diese Nachricht wurde vom KI-Agenten „${eintrag.name}" automatisch erstellt.`;
}

function absenderblock(eintrag) {
  return (
    `   <div style="font-size:13px;color:#222;">` +
    `<strong>i.A. ${maskiere(eintrag.name)}</strong> – ${maskiere(eintrag.rolle)}</div>\n` +
    `   <div style="font-size:11px;color:#888;line-height:1.4;` +
    `margin-top:4px;max-width:780px;">${maskiere(hinweisFuer(eintrag))}</div>`
  );
}

// HTML -> Klartext fuer den text/plain-Teil. Bewusst schlicht: Tags raus,
// Bloecke zu Zeilenumbruechen, Entities zurueck.
function zuText(html) {
  return html
    .replace(/<img[^>]*>/gi, '')
    .replace(/<\/(div|tr|p|table)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&middot;/g, '·')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .split('\n').map((z) => z.trim()).filter((z) => z !== '')
    .join('\n');
}

function signiere(json, leseDatei) {
  if (!json || typeof json !== 'object') {
    return { __signaturFehler: 'kein json-Objekt: ' + String(json) };
  }
  try {
    if (json.signatur === 'none') return json;

    const from = String(json.from || '').trim().toLowerCase();
    const eintrag = ABSENDER[from];
    if (!eintrag) return json;

    let bereich = String(json.bereich || '').trim().toLowerCase();
    if (!BEREICHE.includes(bereich)) bereich = VORGABE_BEREICH;

    const roh = leseDatei(`${BAUSTEIN_VERZEICHNIS}/bereich-${bereich}.html`);
    const sig = roh.replace('{{ABSENDERBLOCK}}', absenderblock(eintrag));

    // Textfassung immer, unabhaengig vom HTML-Teil.
    if (json.text) json.text = `${json.text}\n\n--\n${zuText(sig)}`;

    if (!json.html) return json;

    // Der Lookbehind (?<=[\s"']) verlangt eine echte Attributgrenze vor src.
    // Ohne ihn traefe die Regex auch das Ende eines anderen Attributnamens
    // (z.B. data-src) und schriebe das falsche Attribut um — still falsch
    // statt still abwesend. Muss identisch zu signatur.py bleiben.
    // Logo ans ENDE des attachments-Arrays. Der Index muss die endgueltige
    // Position treffen: "Build Binary Attachments" benennt die Binaerfelder
    // attachment_<index>, und nodemailer nimmt genau diesen Namen als
    // Content-ID. Bei 0 zu beginnen wuerde die erste echte Anlage
    // ueberschreiben.
    const anhaenge = Array.isArray(json.attachments) ? json.attachments : [];
    const mitCid = sig.replace(
      /<img([^>]*?)(?<=[\s"'])src="data:(image\/[a-zA-Z0-9.+-]+);base64,([^"]+)"([^>]*)>/g,
      (_m, vor, mime, daten, nach) => {
        // Index je Treffer neu aus der aktuellen Laenge, wie Pythons
        // `idx = ab_index + len(anhaenge)` innerhalb von zu_cid.repl —
        // sonst bekaeme bei mehreren Bildern jeder Treffer denselben cid.
        const index = anhaenge.length;
        anhaenge.push({
          filename: `logo-${index}.${mime.split('/')[1]}`,
          content: daten,
          mimeType: mime,
          cid: `attachment_${index}`,
        });
        return `<img${vor}src="cid:attachment_${index}"${nach}>`;
      },
    );

    json.html = `${json.html}\n<br>\n${mitCid}`;
    json.attachments = anhaenge;
    return json;
  } catch (err) {
    json.__signaturFehler = String((err && err.message) || err);
    return json;
  }
}

// --- n8n-Aufrufrahmen (angehaengt von patch_relay.py) --------------------
const fsModul = require('fs');
const leseDatei = (p) => fsModul.readFileSync(p, 'utf8');
return $input.all().map((item) => ({ json: signiere(item.json, leseDatei) }));
